CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE service_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description VARCHAR(1000) NOT NULL, price_paise INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO service_items(code,name,description,price_paise,active) VALUES ('PLUMBER','Plumbing','Leaks, taps, pipes and bathroom repairs',29900,TRUE),('ELECTRICIAN','Electrical','Switches, lights, fans and minor electrical repairs',34900,TRUE),('CLEANER','Home Cleaning','Kitchen, bathroom and home cleaning services',49900,TRUE),('APPLIANCE_REPAIR','Appliance Repair','Appliance inspection and repair',39900,TRUE);
CREATE TABLE bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, public_id VARCHAR(40) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, servicer_id BIGINT NULL, service_item_id BIGINT NOT NULL, description VARCHAR(2000) NOT NULL, address VARCHAR(500) NOT NULL, city VARCHAR(120) NOT NULL, scheduled_at DATETIME(6) NOT NULL, agreed_price_paise INT NOT NULL, status VARCHAR(40) NOT NULL, custom_request BOOLEAN NOT NULL DEFAULT FALSE, quote_note VARCHAR(1000), otp_hash VARCHAR(100), otp_expires_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), version BIGINT NOT NULL DEFAULT 0, CONSTRAINT fk_booking_customer FOREIGN KEY(customer_id) REFERENCES users(id), CONSTRAINT fk_booking_servicer FOREIGN KEY(servicer_id) REFERENCES users(id), CONSTRAINT fk_booking_service FOREIGN KEY(service_item_id) REFERENCES service_items(id), INDEX idx_booking_customer(customer_id), INDEX idx_booking_servicer(servicer_id), INDEX idx_booking_status(status));
CREATE TABLE chat_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, body VARCHAR(2000) NOT NULL, sent_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_chat_booking FOREIGN KEY(booking_id) REFERENCES bookings(id), CONSTRAINT fk_chat_sender FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE reviews (id BIGINT PRIMARY KEY AUTO_INCREMENT, booking_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, stars INT NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT fk_review_booking FOREIGN KEY(booking_id) REFERENCES bookings(id), CONSTRAINT fk_review_customer FOREIGN KEY(customer_id) REFERENCES users(id), CONSTRAINT uq_review_booking_customer UNIQUE(booking_id,customer_id));
